
import React, { useEffect, useState } from "react";


import "./styles.css"

import {  fetchEncryptStream, gen16CodeId, getStore, qryStore,  updStore } from "../../../stores/Utils";
import { CloseModal } from "../../../components/DialogHRM";
import { OpenToast } from "../../../components/Toast";



			

const frmNm = "pin-verify-C0de"

const CodeVerifyView  = ({ data, confirm, info, tmk }) => {
	const [initialize, setInitialize] = useState(false);
	const [obs, set_obs] = useState(0);
	const [txt, settxt] = useState("");

	useEffect(() => {
		if (!initialize) {
			setInitialize(true);
			//geteCode();
			set_obs(gen16CodeId())
		}
	});


	
	const handleClose =   (v) => {
		data?.modalID && CloseModal({id:data?.modalID});
	}

	const validateCode =  async (v) => {
		
		let bdyq2 = {...getStore(qryStore())?.validt_notf_code};
		bdyq2.params = {
			businessId:  getStore("profileUser")?.businessId,
			phoneNumber: getStore("profileUser")?.phoneNumber,
			":code": txt.toLocaleUpperCase(),
			":search1": tmk
		};

		const res = fetchEncryptStream(bdyq2);
		const td = await res;
		if (td && !td.error) {
			//OpenToast({ text: "Cerrando el año y generando el asiento de apertura", timeout: 3500 });
			confirm && confirm();
			handleClose();
		}else{
			OpenToast({ text: "hubo un error con el codigo2", timeout: 1500 });
			handleClose();
		}
	}



	
	const handleInput = (v) => {
		settxt(v.target.value);
		
	};

	const handleKey = (v) => {
		if(v.keyCode===13){
			
		}
		if(v.keyCode===27){
			
		}
	};

 	// Enter the code we sent to

	return (
		<div style={{
			maxHeight: "80vh",
			width: "560px",
			overflow: "auto",
			background: "var(--hrm_palette-general-background-b)",
			borderRadius: 13,
			padding: "10px 19px"
		}}>
			<div className="_dsplFlx pinCode" >
				<h1 className="">
					NECESITAMOS VERIFICACION ANTES DE CERRAR LA CONTABILIDAD
				</h1>
				<div className="flexSpace"/>
				
			</div>

			<div className="pinCode">
				<div>
					<p>
						{`Ingresa el código que le enviamos a (***) ***-*${info?.phoneNumber.slice(info?.phoneNumber.length-3,info?.phoneNumber.length)}`}
					</p>

				</div>
				<div className="_dsplFlx">
					<div className="flexSpace"/>
					<input 
						maxLength="6" 
						//pattern="[0-9||A-Z]*" 
						placeholder="------" 
						
						required="required" 
						autoComplete="one-time-code" 
						size="6" 
						type="text"
						id="multifactor_code"
						onChange={handleInput}
						onKeyDown={handleKey}
					/>
					<div className="flexSpace"/>
				</div>
			</div>
			<div className="_dsplFlx " style={{padding: 21}}>
				<div className="flexSpace"/>
				<div className="">
					<p className="group_title addBtn" onClick={handleClose}>
						Cancelar
					</p>
				</div>
				<div className="">
					<p className="group_title addBtn red" onClick={validateCode}>
					Verificar
					</p>
					
				</div>

			</div>
		

			
		</div>
	);
};

export default CodeVerifyView;